import{_ as i,a0 as r,w as m,s,ao as n,I as a,x as p,a1 as f,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何使用ffmpeg從視頻中提取圖片 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用ffmpeg從視頻中提取圖片 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用ffmpeg從視頻中提取圖片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用ffmpeg從視頻中提取圖片 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140607 How To Extract Images From Videos Using ffmpeg","title":"如何使用ffmpeg從視頻中提取圖片","tag":"201406","desc":""},"relativePath":"201406/20140607 How To Extract Images From Videos Using ffmpeg.md","filePath":"[post].md"}'),l={name:"201406/20140607 How To Extract Images From Videos Using ffmpeg.md"};function g(d,e,u,x,T,w){const t=r("Link");return m(),s("div",null,[e[11]||(e[11]=n(`<h1 id="如何使用ffmpeg從視頻中提取圖片" tabindex="-1">如何使用ffmpeg從視頻中提取圖片 <a class="header-anchor" href="#如何使用ffmpeg從視頻中提取圖片" aria-label="Permalink to “如何使用ffmpeg從視頻中提取圖片”">​</a></h1><p>你曾想過從一個視頻文件中提取圖片嗎？在Linux下就可以，在這個教程中我將使用ffmpeg來從視頻中獲取圖片。</p><h3 id="什麼是ffmpeg-what-is-ffmpeg" tabindex="-1">什麼是ffmpeg？What is ffmpeg? <a class="header-anchor" href="#什麼是ffmpeg-what-is-ffmpeg" aria-label="Permalink to “什麼是ffmpeg？What is ffmpeg?”">​</a></h3><p>ffmpeg是一個非常有用的命令列程序，它可以用來轉碼媒體文件。它是領先的多媒體框架FFmpeg的一部分，其有很多功能，比如解碼、編碼、轉碼、混流、分離、轉化為流、過濾以及播放幾乎所有的由人和機器創建的媒體文件。</p><p>在這個框架中包含有各種工具，每一個用於完成特定的功能。例如，ffserver能夠將多媒體文件轉化為用於實時廣播的流，ffprobe用於分析多媒體流，ffplay可以當作一個簡易的媒體播放器，<strong>ffmpeg</strong>則能夠轉換多媒體文件格式。</p><p>如果你感興趣，以下列出的是FFmpeg框架中包含的開發者庫：</p><ul><li>libavutil是一個包含簡化編程功能的庫，其中包括隨機數生成器，數據結構，數學代碼，核心多媒體工具等更多東西。</li><li>libavcodec是一個包含音頻/視頻解碼器和編碼器的庫。</li><li>libavformat是一個包含了多媒體格式的分離器和混流器的庫。</li><li>libavdevice是一個包含輸入輸出設備的庫，用於捕捉和渲染很多來自常用的多媒體輸入/輸出軟件框架的數據，包括Video4Linux，Video4Linux2，VfW和ALSA。</li><li>libavfilter是一個包含媒體過濾器的庫。</li><li>libswscale是一個用於執行高度優化的圖像縮放和顏色空間/像素格式轉換操作的庫。</li><li>libswresample是一個用於執行高度優化的音頻重採樣，重新矩陣和取樣格式轉換操作的庫。</li></ul><p><strong>注意</strong>：ffmpeg和FFmpeg不是同一個東西。FFmpeg是框架，而ffmpeg是一個其中的一個功能。</p><h3 id="開始行動" tabindex="-1">開始行動 <a class="header-anchor" href="#開始行動" aria-label="Permalink to “開始行動”">​</a></h3><p>如果你想跟着教程做，你需要在你的linux機中安裝ffmpeg命令列功能。Ubuntu用户可以在終端運行以下命令輕鬆安裝ffmpeg功能。</p><pre><code>sudo apt-get install ffmpeg
</code></pre><p>Fedora用户可以從源中直接安裝ffmpeg。</p><pre><code>yum install ffmpeg
</code></pre><p>或者你可以編譯源代碼。在你使用源代碼編譯並安裝它之前，你需要從官網上下載源代碼，使用以下命令。</p><pre><code>wget http://www.ffmpeg.org/releases/ffmpeg-2.2.3.tar.bz2
</code></pre><p>用下面命令解壓文檔。</p><pre><code>tar -xvjf ffmpeg-2.2.3.tar.bz2
</code></pre><p>文檔解壓完成後進入解壓後的目錄運行以下命令。</p><pre><code>./configure
make
</code></pre><p>編譯完成後運行下面的命令安裝ffmpeg。</p><pre><code>su -c &#39;make install&#39;
</code></pre><p>全部的事情並沒有完成，而你將要做的所有事就是在終端鍵入一些命令而且將能夠從任何視頻文件中抓取圖片。</p><p>在做之後的步驟前，確保你在想要提取圖片的視頻文件的目錄下。使用cd命令切換到正確的目錄。教程中我使用的視頻在我的桌面上，我用以下命令將目錄切換到我的桌面。</p><pre><code>cd /home/oltjano/Desktop
</code></pre><p>之後我使用以下命令從視頻中提取圖片。</p><pre><code>ffmpeg -i &quot;你是我的小呀小蘋果兒.mp4&quot; -r 1 -q:v 2 -f image2 image-3%d.jpeg
</code></pre><p><strong>-i</strong>選項用來獲取輸入文件，在這裏是視頻文件名<strong>你是我的小呀小蘋果兒.mp4</strong>，-r選項設置每秒提取圖片的幀數。我想要每秒提取一幀。</p><p>之後有一個重要的選項是-q:v，應該留意這個選項並且我很喜歡用它，它用來設置提取到的圖片質量。我總是設置值為2來從視頻中獲取高質量圖片。</p><hr>`,29)),a("p",null,[e[1]||(e[1]=p("via: ",-1)),f(t,{href:"http://www.unixmen.com/extract-images-videos-using-ffmpeg/"},{default:o(()=>[...e[0]||(e[0]=[p("http://www.unixmen.com/extract-images-videos-using-ffmpeg/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=p("譯者：",-1)),f(t,{href:"https://github.com/linuhap"},{default:o(()=>[...e[2]||(e[2]=[p("linuhap",-1)])]),_:1}),e[5]||(e[5]=p(" 校對：",-1)),f(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[3]||(e[3]=[p("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=p("本文由 ",-1)),f(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原創翻譯，",-1)),f(t,{href:"http://linux.cn/"},{default:o(()=>[...e[7]||(e[7]=[p("Linux中國",-1)])]),_:1}),e[10]||(e[10]=p(" 榮譽推出",-1))])])}const v=i(l,[["render",g]]);export{h as __pageData,v as default};
